import pty, os, subprocess, select, time, struct, fcntl, termios
def test_one(prompt, byte):
    master, slave = pty.openpty()
    fcntl.ioctl(slave, termios.TIOCSWINSZ, struct.pack("HHHH", 24, 80, 0, 0))
    p = subprocess.Popen(["./executable","-p",prompt], stdin=slave, stdout=slave, stderr=slave, close_fds=True)
    os.close(slave)
    import fcntl as f2
    flags = f2.fcntl(master, f2.F_GETFL)
    f2.fcntl(master, f2.F_SETFL, flags | os.O_NONBLOCK)
    def drain(timeout=0.8):
        data=b""
        end=time.time()+timeout
        while time.time()<end:
            r,_,_ = select.select([master], [], [], 0.2)
            if r:
                try:
                    chunk=os.read(master, 65536)
                    if not chunk: break
                    data+=chunk
                    end=time.time()+0.2
                except OSError: break
        return data
    drain(1.0)
    os.write(master, bytes([byte]))
    time.sleep(0.4)
    d=drain(0.8)
    alive=p.poll() is None
    # determine: green/red/nothing/exit
    if not alive:
        res="exit"
    elif b"38;5;2" in d:
        res="green(correct)"
    elif b"38;5;1" in d:
        res="red(wrong)"
    elif len(d)>30:
        res=f"other len{len(d)} {repr(d[:100])}"
    else:
        res=f"ignored len{len(d)}"
    print(f"byte {hex(byte)} ({repr(chr(byte))}) -> {res}")
    try: p.terminate()
    except: pass
    try: p.wait(timeout=1)
    except: p.kill()
    os.close(master)

for b in list(range(0x00, 0x20)):
    test_one("a", b)
PY"}

