# Quick prototype for CLI parsing to test logic
import sys, os, re, math

def jaro_winkler(s1, s2):
    # Implement Jaro-Winkler as in strsim crate?
    # For now, use simple Levenshtein-based? Need to match clap's behavior.
    # Let's implement Jaro and Winkler.
    if s1==s2:
        return 1.0
    len1, len2 = len(s1), len(s2)
    if len1==0 or len2==0:
        return 0.0
    match_dist = max(len1, len2)//2 -1
    if match_dist<0:
        match_dist=0
    s1_matches=[False]*len1
    s2_matches=[False]*len2
    matches=0
    for i in range(len1):
        start=max(0, i-match_dist)
        end=min(i+match_dist+1, len2)
        for j in range(start, end):
            if not s2_matches[j] and s1[i]==s2[j]:
                s1_matches[i]=True
                s2_matches[j]=True
                matches+=1
                break
    if matches==0:
        return 0.0
    # transpositions
    k=0
    trans=0
    for i in range(len1):
        if s1_matches[i]:
            while not s2_matches[k]:
                k+=1
            if s1[i]!=s2[k]:
                trans+=1
            k+=1
    trans//=2
    jaro=(matches/len1 + matches/len2 + (matches-trans)/matches)/3.0
    # winkler boost for prefix
    prefix=0
    for i in range(min(4, min(len1,len2))):
        if s1[i]==s2[i]:
            prefix+=1
        else:
            break
    return jaro + prefix*0.1*(1-jaro)

# Test against observed: e vs english should be <0.8, en vs english >0.8?
for s in ["e","en","eng","engl","xyz","1k"]:
    print(s, jaro_winkler(s,"english"), jaro_winkler(s,"english1k"), jaro_winkler(s,"english10k"))
