            base=WORDS_ENGLISH10K
        else:
            base=WORDS_ENGLISH
        if not base:
            # fallback for testing without lists: use dummy?
            base=["hello","world","test"]
        if n<=0:
            return ""
        n=min(n, len(base))
        words=random.sample(base, n)
        return " ".join(words)

