def get_term_size():
    try:
        import shutil
        sz = shutil.get_terminal_size()
        return sz.columns, sz.lines
    except:
        return 80, 24

def wrap_prompt(prompt, width):
    max_w = width - 10
    if max_w < 10:
        max_w = 10
    if not prompt:
        return []
    words = prompt.split(" ")
    lines=[]
    cur=""
    for w in words:
        # handle long words that exceed max_w: split
        while len(w) > max_w:
            # if cur not empty, flush cur first?
            if cur:
                lines.append(cur)
                cur=""
            lines.append(w[:max_w])
            w=w[max_w:]
        if cur=="":
            # first word in line?
            if len(w) <= max_w:
                cur=w
            else:
                # shouldn't happen (already split)
                cur=w
        else:
            if len(cur)+1+len(w) <= max_w:
                cur=cur+" "+w
            else:
                lines.append(cur)
                cur=w
    if cur!="":
        lines.append(cur)
    # Edge: prompt with multiple spaces? Our split loses extra spaces. But prompts are single spaces, fine.
    # Also need to handle prompt starting/ending with space? Unlikely. Ignore.
    return lines

