WORDS_ENGLISH = []
WORDS_ENGLISH1K = []
WORDS_ENGLISH10K = []

def get_prompt_text(vals):
    import random
    if vals.get("p") is not None:
        return vals["p"]
    if vals.get("f") is not None:
        try:
            s=vals["f"]
            if s.startswith("+"):
                s=s[1:]
            n=int(s)
        except:
            n=0
        if n<=0:
            return ""
        base=WORDS_ENGLISH10K if WORDS_ENGLISH10K else ["hello","world"]
        sents=[]
        for _ in range(n):
            k=random.randint(5,10)
            if len(base)>=k:
                words=random.sample(base,k)
            else:
                words=[random.choice(base) for _ in range(k)]
            words=[w.lower() for w in words]
            if words:
                words[0]=words[0].capitalize()
            sents.append(" ".join(words)+".")
        return " ".join(sents)
    else:
        try:
            s=vals.get("w","15")
            if s.startswith("+"):
                s=s[1:]
            n=int(s)
        except:
            n=15
        lang=vals.get("l","english")
        if lang=="english":
            base=WORDS_ENGLISH
        elif lang=="english1k":
            base=WORDS_ENGLISH1K
        elif lang=="english10k":
            base=WORDS_ENGLISH10K
        else:
            base=WORDS_ENGLISH
        if not base:
            base=["hello","world","test"]
        if n<=0:
            return ""
        n=min(n,len(base))
        import random
        words=random.sample(base,n)
        return " ".join(words)

def get_term_size():
    try:
        import shutil
        sz=shutil.get_terminal_size()
        return sz.columns, sz.lines
    except:
        return 80,24

def wrap_prompt(prompt, width):
    max_w=width-10
    if max_w<10:
        max_w=10
    if not prompt:
        return []
    words=prompt.split(" ")
    lines=[]
    cur=""
    for w in words:
        while len(w)>max_w:
            if cur:
                lines.append(cur)
                cur=""
            lines.append(w[:max_w])
            w=w[max_w:]
        if cur=="":
            cur=w
        else:
            if len(cur)+1+len(w)<=max_w:
                cur=cur+" "+w
            else:
                lines.append(cur)
                cur=w
    if cur!="":
        lines.append(cur)
    return lines

def get_config_dir():
    xdg=os.environ.get("XDG_CONFIG_HOME")
    if xdg and xdg.strip()!="":
        return os.path.join(xdg,"thokr")
    home=os.environ.get("HOME")
    if home and home.strip()!="":
        return os.path.join(home,".config","thokr")
    return None

def write_log(vals, elapsed, wpm_str, acc_str, sd_str):
    cfg=get_config_dir()
    if cfg is None:
        return
    try:
        os.makedirs(cfg,exist_ok=True)
        log_path=os.path.join(cfg,"log.csv")
        if vals.get("f") is not None:
            num_words_str="0"
        else:
            s=vals.get("w","15")
            if s.startswith("+"):
                s=s[1:]
            try:
                num_words_str=str(int(s))
            except:
                num_words_str=s
        if vals.get("s") is not None:
            try:
                s=vals.get("s")
                if s.startswith("+"):
                    s=s[1:]
                ival=int(s)
                num_secs_str=f"{float(ival):.2f}"
            except:
                num_secs_str=""
        else:
            num_secs_str=""
        try:
            date_str=datetime.datetime.now().strftime("%a %b %e %T %Y")
        except:
            date_str=time.strftime("%a %b %e %T %Y")
        elapsed_str=f"{elapsed:.2f}"
        need_header=False
        if not os.path.exists(log_path):
            need_header=True
        else:
            try:
                if os.path.getsize(log_path)==0:
                    need_header=True
            except:
                need_header=True
        with open(log_path,"a",newline="") as f:
            if need_header:
                f.write("date,num_words,num_secs,elapsed_secs,wpm,accuracy,std_dev\n")
            f.write(f"{date_str},{num_words_str},{num_secs_str},{elapsed_str},{wpm_str},{acc_str},{sd_str}\n")
    except:
        pass

