def run_tui(vals):
    prompt = get_prompt_text(vals)
    num_secs = None
    if vals.get("s") is not None:
        try:
            s=vals["s"]
            if s.startswith("+"):
                s=s[1:]
            num_secs=int(s)
        except:
            num_secs=None
