    except:
        pass
    try:
        sys.stdout.write("\x1b[?1049h\x1b[?25l")
        sys.stdout.flush()
    except:
        pass
    def restore():
        try:
            sys.stdout.write("\x1b[?1049l\x1b[?25h")
            sys.stdout.flush()
        except:
            pass
        try:
            if orig_term is not None:
                termios.tcsetattr(stdin_fd,termios.TCSADRAIN,orig_term)
        except:
            pass
    try:
        current_prompt=prompt
        if current_prompt=="":
            mode="results"
            stats_empty=compute_stats("",[],0,timed_out=False)
            draw_results_screen(stats_empty)
            last_stats=stats_empty
            pos=0
            correct=[]
            start_time=None
            last_time=None
        else:
            mode="prompt"
            pos=0
            correct=[None]*len(current_prompt)
            start_time=None
            last_time=None
            if num_secs is not None:
                timer_text=f"{float(num_secs):.1f}"
            else:
                timer_text=None
            draw_prompt_full(current_prompt,pos,correct,timer_text)
            last_timer_text=timer_text
        last_size=get_term_size()
        while True:
            cur_size=get_term_size()
            if cur_size!=last_size:
                last_size=cur_size
                if mode=="prompt":
                    if num_secs is not None and start_time is not None:
                        elapsed_now=time.monotonic()-start_time
                        remaining=num_secs-elapsed_now
                        if remaining<0:
                            remaining=0
                        timer_text=f"{remaining:.1f}"
                    elif num_secs is not None:
                        timer_text=f"{float(num_secs):.1f}"
                    else:
                        timer_text=None
                    draw_prompt_full(current_prompt,pos,correct,timer_text)
                    try:
                        last_timer_text=timer_text
                    except:
                        pass
                else:
                    try:
                        draw_results_screen(last_stats)
                    except:
                        pass
            rlist,_,_=select.select([sys.stdin],[],[],0.05)
            if mode=="prompt" and num_secs is not None and start_time is not None:
                now=time.monotonic()
                elapsed_now=now-start_time
                if elapsed_now>=num_secs:
                    if last_time is not None and start_time is not None:
                        typing_dur=last_time-start_time
                    else:
                        typing_dur=0
                    stats=compute_stats(current_prompt,correct,typing_dur,timed_out=True)
                    draw_results_screen(stats)
                    try:
                        write_log(vals,elapsed_now,stats["wpm_str"],stats["acc_str"],stats["sd_str"])
                    except:
                        pass
                    mode="results"
                    last_stats=stats
                    continue
                else:
                    remaining=num_secs-elapsed_now
                    if remaining<0:
                        remaining=0
                    new_timer=f"{remaining:.1f}"
                    try:
                        if new_timer!=last_timer_text:
                            last_timer_text=new_timer
                            draw_prompt_full(current_prompt,pos,correct,new_timer)
                    except NameError:
                        last_timer_text=new_timer
                        draw_prompt_full(current_prompt,pos,correct,new_timer)
